#!/usr/bin/env bash
# Runs inside the emulator: installs the APK, enables PsiBoard, and screenshots real renders.
set -u
PKG=com.psiboard.ime
IME=$PKG/.PsiBoardService
OUT=shots
mkdir -p $OUT
adb wait-for-device
adb install -r app/build/outputs/apk/debug/app-debug.apk
# enable the debug intent hooks (they only run when this marker exists in the app's private folder)
adb shell "run-as $PKG sh -c 'mkdir -p files && touch files/ci_hooks'"
adb shell "run-as $PKG ls files" > $OUT/hooks.txt 2>&1
adb shell settings put secure show_ime_with_hard_keyboard 1
adb shell wm size 720x1560
adb shell wm density 320
sleep 2

# Select PsiBoard as the current keyboard. The package manager needs a moment after an install / force-stop,
# so retry until the system confirms.
set_ime() {
  local i
  for i in 1 2 3 4 5 6 7 8; do
    local e s
    e=$(adb shell ime enable $IME 2>&1 | tr -d '\r')
    s=$(adb shell ime set $IME 2>&1 | tr -d '\r')
    echo "try $i: $e | $s" >> $OUT/ime.txt
    case "$s" in *selected*) return 0;; esac
    sleep 2
  done
  return 1
}

# shoot NAME [am-extras...]
#   TAP=0     don't focus the text field (settings screen only)
#   TYPE=abc  type text after the keyboard opened
#   POST_TAP=x,y  tap a point once the keyboard is open (panels)
#   SCROLL=1  scroll the settings page down
#   TAPS="x,y x,y"  tap several points in sequence (typing on the keyboard)
#   ROTATE=1  landscape
#   HOLD=x,y  long-press a point while the screenshot is taken (popups)
#   NIGHT=1   system dark mode (affects theme_mode=auto and the settings screen)
shoot() {
  local name=$1; shift
  adb shell cmd uimode night $([ "${NIGHT:-0}" = "1" ] && echo yes || echo no) > /dev/null 2>&1
  # force-stop makes Android drop the current IME if it belongs to the stopped package
  # (the broadcast reaches the IME manager asynchronously), so wait, then apply settings, then select the IME
  adb shell am force-stop $PKG
  sleep 2
  adb shell settings put system accelerometer_rotation 0
  adb shell settings put system user_rotation ${ROTATE:-0}
  adb shell input keyevent KEYCODE_HOME
  sleep 1
  adb shell am start -W -n $PKG/.SettingsActivity --ez psi_reset true "$@" > /dev/null
  sleep 3
  echo "== $name" >> $OUT/ime.txt
  set_ime
  sleep 2
  if [ "${TAP:-1}" = "1" ]; then
    adb shell uiautomator dump /sdcard/ui.xml > /dev/null 2>&1
    adb pull /sdcard/ui.xml /tmp/ui.xml > /dev/null 2>&1
    adb shell input tap $(python3 .github/scripts/edit_center.py /tmp/ui.xml)
    sleep 3
  fi
  if [ -n "${TYPE:-}" ]; then adb shell input text "$TYPE"; sleep 2; fi
  if [ -n "${SCROLL:-}" ]; then adb shell input swipe 360 1300 360 400 400; sleep 1; adb shell input swipe 360 1300 360 700 400; sleep 1; fi
  if [ -n "${TAPS:-}" ]; then for xy in $TAPS; do adb shell input tap ${xy%,*} ${xy#*,}; sleep 0.4; done; sleep 1; fi
  if [ -n "${POST_TAP:-}" ]; then adb shell input tap ${POST_TAP%,*} ${POST_TAP#*,}; sleep 2; fi
  if [ -n "${HOLD:-}" ]; then
    local hx=${HOLD%,*} hy=${HOLD#*,}
    adb shell input swipe $hx $hy $hx $hy 3000 &
    sleep 1.8
  fi
  adb exec-out screencap -p > $OUT/$name.png
  echo "default_input_method=$(adb shell settings get secure default_input_method | tr -d '\r')" >> $OUT/ime.txt
  wait
}

# scenario list is generated by scenarios.sh so it can change without touching this file
source .github/scripts/scenarios.sh

adb logcat -d | grep -iE "psiboard|AndroidRuntime|FATAL" | tail -120 > $OUT/log.txt || true
ls -la $OUT
